using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class RemoveRoadDetailMeshes{static RemoveRoadDetailMeshes(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("RemoveRoadDetailMeshes.request"))return;File.Delete("RemoveRoadDetailMeshes.request");try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");int roots=0;foreach(var g in scene.GetRootGameObjects().Where(g=>g.name=="City Road Surface Details"||g.name=="City Crossing Curb Ramps").ToArray()){UnityEngine.Object.DestroyImmediate(g);roots++;}if(scene.GetRootGameObjects().Any(g=>g.name=="City Road Surface Details"||g.name=="City Crossing Curb Ramps"))throw new Exception("Road detail roots remain");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);string folder="Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadSurfaceDetails";if(AssetDatabase.IsValidFolder(folder)&&!AssetDatabase.DeleteAsset(folder))throw new Exception("Unable to remove generated road detail assets");foreach(var p in new[]{"Assets/Scenes/Oasis/RoadAtlas/Shaders/RandomRoadWear.hlsl","Assets/Scenes/Oasis/RoadAtlas/Shaders/CityDetailLitForwardPass.hlsl","Assets/Scenes/Oasis/RoadAtlas/Shaders/CityDetailLitGBufferPass.hlsl"})if(AssetDatabase.LoadMainAssetAtPath(p))AssetDatabase.DeleteAsset(p);AssetDatabase.SaveAssets();AssetDatabase.Refresh();File.WriteAllText("FinalEnvironmentRoadReview/RemovedRoadDetailMeshes.txt","SUCCESS removed "+roots+" added road-detail scene roots and generated mesh/prefab folder. Pre-road-polish shaders restored, procedural wear rolled back. Original road geometry, UV fixes, fences, beach and city props retained; no new texture-only detail implemented.");}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/RemovedRoadDetailMeshes.txt",e.ToString());Debug.LogException(e);}}}
